        <script>
                     
            $(document).ready(function() {
                // যখন ইউজার ছবি আপলোড করবে
                $("#post_image").change(function(event) {
                    // FileReader ব্যবহার করে ছবির প্রিভিউ দেখানো
                    var reader = new FileReader();
                    
                    reader.onload = function(e) {
                        // প্রিভিউ ছবি সেট করুন
                        $("#previewImage").attr("src", e.target.result);
                        $("#imagePreviewContainer").show(); // প্রিভিউ কনটেইনারটি দেখান
                    }
                    
                    // ছবির ফাইল রিড করুন
                    reader.readAsDataURL(this.files[0]);
                });
            });
            // Swiper initialization
            const swiper = new Swiper('.mySwiper', {
                slidesPerView: 1,
                spaceBetween: 30,
                loop: true,
                autoplay: {
                    delay: 2500,
                    disableOnInteraction: false,
                },
                breakpoints: {
                    576: {
                        slidesPerView: 2,
                    },
                    768: {
                        slidesPerView: 3,
                    },
                    992: {
                        slidesPerView: 4,
                    }
                }
            }); 



            



var words = ['Design and Developed by ViretaDev', 'Copyright @ ViretaDev'],
    part,
    i = 0,
    offset = 0,
    len = words.length,
    forwards = true,
    skip_count = 0,
    skip_delay = 30,
    speed = 80;
var wordflick = function () {
    setInterval(function () {
        if (forwards) {
            if (offset >= words[i].length) {
                ++skip_count;
                if (skip_count == skip_delay) {
                    forwards = false;
                    skip_count = 0;
                }
            }
        }
        else {
            if (offset == 0) {
                forwards = true;
                i++;
                offset = 0;
                if (i >= len) {
                    i = 0;
                }
            }
        }
        part = words[i].substr(0, offset);
        if (skip_count == 0) {
            if (forwards) {
                offset++;
            }
            else {
                offset--;
            }
        }
        $('.glos_text_word').text(part);
    }, speed);
};

$(document).ready(function() {
    wordflick();
    $('.glos_text_word_img_srch').attr('src', `data:image/png;base64,`);
});





        </script>

